import { after } from 'next/server'
import { headers } from 'next/headers'
import { logPageView } from './analytics'

export default async function Home() {
  // Read request data before `after` — request APIs like headers()
  // are not available inside the after callback in server components.
  const userAgent = (await headers()).get('user-agent') || 'unknown'

  after(async () => {
    await logPageView('/', userAgent)
  })

  return (
    <main>
      <h1>Welcome</h1>
      <p>Thanks for visiting! We hope you enjoy your stay.</p>
    </main>
  )
}

